package bookstore

// Cost returns the minimum price, in cents, of the given basket of books,
// grouping the books to get as big a discount as possible.
// Each book is identified by an integer from 1 to 5.
func Cost(books []int) int {
	var counts [5]int
	for _, book := range books {
		counts[book-1]++
	}
	return minCost(counts)
}

// groupPrice[k] is the price, in cents, of a group of k distinct books.
var groupPrice = [6]int{
	0,    // 0 books
	800,  // 1 book: no discount
	1520, // 2 books: 5% discount
	2160, // 3 books: 10% discount
	2560, // 4 books: 20% discount
	3000, // 5 books: 25% discount
}

// minCost computes the minimum cost of the remaining books, where
// counts[t] is the number of copies of title t still to buy. It tries
// every possible next group (one copy of each title in a non-empty
// subset of the titles) and memoizes results by the count vector.
func minCost(counts [5]int) int {
	memo := make(map[[5]int]int)

	var solve func(c [5]int) int
	solve = func(c [5]int) int {
		if c == ([5]int{}) {
			return 0
		}
		if v, ok := memo[c]; ok {
			return v
		}
		best := -1
		for mask := 1; mask < 1<<5; mask++ {
			size := 0
			next := c
			valid := true
			for t := 0; t < 5; t++ {
				if mask&(1<<t) != 0 {
					if c[t] == 0 {
						valid = false
						break
					}
					next[t]--
					size++
				}
			}
			if !valid {
				continue
			}
			cost := groupPrice[size] + solve(next)
			if best < 0 || cost < best {
				best = cost
			}
		}
		memo[c] = best
		return best
	}

	return solve(counts)
}
